import{_ as e,o,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Direction and reporting","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/direction/pilotage.md","filePath":"src/en/guide/direction/pilotage.md"}'),i={name:"en/guide/direction/pilotage.md"};function a(s,t,d,h,c,l){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="direction-and-reporting" tabindex="-1">Direction and reporting <a class="header-anchor" href="#direction-and-reporting" aria-label="Permalink to &quot;Direction and reporting&quot;">​</a></h1><p>Two pages of the <strong>Overview</strong> section give the overall view of activity, <strong>read-only</strong>: the <strong>Direction view</strong> and <strong>Reporting</strong>. They rest on the same periods, the same filters and the same definitions.</p><table tabindex="0"><thead><tr><th>Page</th><th>For whom</th><th>Particularity</th></tr></thead><tbody><tr><td><strong>Direction view</strong></td><td>Direction, Administrator</td><td>Shows what was paid out and the margin</td></tr><tr><td><strong>Reporting</strong></td><td>Pedagogical Coordinator, Administrator</td><td>No payout or margin; with attendance and grades; CSV export</td></tr></tbody></table><h2 id="choosing-what-you-look-at" tabindex="-1">Choosing what you look at <a class="header-anchor" href="#choosing-what-you-look-at" aria-label="Permalink to &quot;Choosing what you look at&quot;">​</a></h2><p>Both pages cover <strong>cohorts that start in the chosen year</strong> (the current year by default). Then filter by <strong>program</strong> and by <strong>promotion</strong>. A postponed or cancelled cohort counts neither in places nor in zones.</p><h2 id="the-direction-view" tabindex="-1">The Direction view <a class="header-anchor" href="#the-direction-view" aria-label="Permalink to &quot;The Direction view&quot;">​</a></h2><p><strong>Training:</strong></p><ul><li>cohorts <strong>by status</strong>;</li><li><strong>headcount zones</strong> (Fragile, Viable, Comfortable), frozen at the start for started cohorts, current for upcoming cohorts;</li><li>the <strong>fill rate</strong>: learners over places.</li></ul><p><strong>Success rate.</strong> It covers <strong>completed</strong> cohorts: certified learners over learners who finished. A learner &quot;who finished&quot; is one who completed a finished cohort, certified or not; <strong>a drop-out after signing counts as a failure</strong>.</p><p><strong>Finance:</strong></p><table tabindex="0"><thead><tr><th>Indicator</th><th>Definition</th></tr></thead><tbody><tr><td>Invoiced</td><td>Net of cancellation credit notes</td></tr><tr><td>Collected</td><td>Net of refunds</td></tr><tr><td>Still to collect</td><td>Including the overdue amount</td></tr><tr><td>Paid out</td><td>Trainers&#39;, coaches&#39; and jury members&#39; pay, referrers&#39; commissions, and, in the overall view, marketing partners&#39; invoices paid in the year</td></tr><tr><td>Gross margin</td><td>Collected minus paid out</td></tr></tbody></table><p>A detail <strong>by program</strong> and <strong>by promotion</strong> accompanies these figures.</p><p><strong>L&#39;Éclosion participations.</strong> The portfolio lists participations validated by the investment committee, all cycles together: project, cycle, type, share and validation date.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Reporting repeats fill, success (with the number of partial attestations), invoiced, collected and outstanding, and adds:</p><ul><li><strong>attendance</strong>: the time present of confirmed learners, present or late, over the length of the sessions recorded for them;</li><li>the <strong>overall average</strong>: the average of the weighted averages of learners with at least one graded block, out of 20.</li></ul><p>The detail is <strong>by program</strong>, <strong>by promotion</strong>, then <strong>one line per cohort</strong>, which leads to the cohort&#39;s page.</p><p><strong>Export as CSV</strong> produces the list of the selection&#39;s cohorts (semicolon separator, UTF-8, in the user&#39;s language).</p><h2 id="the-investment-committee" tabindex="-1">The investment committee <a class="header-anchor" href="#the-investment-committee" aria-label="Permalink to &quot;The investment committee&quot;">​</a></h2><p>The Direction also sits on L&#39;Éclosion&#39;s <strong>investment committee</strong>, with the Incubation Officer and the Pedagogical Coordinator: see <a href="./../activites/eclosion.html#the-participation-and-the-investment-committee">L&#39;Éclosion</a>. It is the only place where the Direction acts, the rest of its pages being read-only.</p>',20)])])}const m=e(i,[["render",a]]);export{p as __pageData,m as default};
